      <el-tabs v-model="tab"><el-tab-pane label="固定规则审核" name="profiles"><el-form-item label="固定规则筛选"><el-select v-model="profileRule" clearable aria-label="治理固定规则筛选" placeholder="全部规则"><el-option v-for="option in options" :key="option.rule_id" :value="option.rule_id" :label="option.rule_id" /></el-select></el-form-item><el-button type="primary" @click="openCreate">新建固定规则审核草稿</el-button><el-table :data="items" v-loading="loading" empty-text="没有规则审核版本"><el-table-column prop="name" label="审核版本名称" /><el-table-column prop="rule_id" label="固定规则" /><el-table-column prop="recipe_digest" label="规则摘要" min-width="240" /><el-table-column label="状态与版本"><template #default="{ row }">{{ statusLabel(row.status) }} · v{{ row.revision }}</template></el-table-column><el-table-column label="核对"><template #default="{ row }"><el-button @click="inspect(row)">核对规则审核版本</el-button></template></el-table-column></el-table></el-tab-pane>
        <el-tab-pane label="NEWS2评估全院审计" name="assessments"><el-form inline @submit.prevent="load"><el-form-item label="患者ID"><el-input v-model="filters.patient_id" aria-label="NEWS2治理患者ID" inputmode="numeric" /></el-form-item><el-form-item label="原住院ID"><el-input v-model="filters.admission_id" aria-label="NEWS2治理原住院ID" /></el-form-item><el-form-item label="状态"><el-select v-model="filters.status" aria-label="NEWS2治理来源状态" clearable placeholder="全部状态"><el-option label="活动" value="active" /><el-option label="已撤销" value="revoked" /></el-select></el-form-item><el-button native-type="submit" :loading="loading">查询全院NEWS2评估</el-button></el-form><p>来源治理、人工适用性声明和临床效果验证分别记录。超级管理员保留失效原版本作审计，不因能读取冻结值就允许当前计算。</p><el-table :data="items" v-loading="loading" empty-text="没有匹配的评估来源"><el-table-column prop="assessment_id" label="评估来源ID" min-width="250" /><el-table-column label="原患者与住院" min-width="230"><template #default="{ row }">#{{ row.patient_id }} · {{ row.admission_id }}</template></el-table-column><el-table-column prop="observed_at" label="原观察时刻" min-width="220" /><el-table-column label="状态与版本"><template #default="{ row }">{{ statusLabel(row.status) }} · v{{ row.revision }}</template></el-table-column><el-table-column label="核对"><template #default="{ row }"><el-button @click="inspect(row)">核对冻结NEWS2评估</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="成人AKI评估全院审计" name="aki_assessments"><el-form inline @submit.prevent="load"><el-form-item label="患者ID"><el-input v-model="filters.patient_id" aria-label="AKI治理患者ID" inputmode="numeric" /></el-form-item><el-form-item label="原住院ID"><el-input v-model="filters.admission_id" aria-label="AKI治理原住院ID" /></el-form-item><el-form-item label="状态"><el-select v-model="filters.status" aria-label="AKI治理来源状态" clearable placeholder="全部状态"><el-option label="活动" value="active" /><el-option label="已撤销" value="revoked" /></el-select></el-form-item><el-button native-type="submit" :loading="loading">查询全院成人AKI评估</el-button></el-form><p>只审计原来源、人工声明和治理状态；来源有效不等于计算资料完整，不自动排除AKI、启用业务或升级临床验证。</p><el-table :data="items" v-loading="loading" empty-text="没有匹配的AKI评估来源"><el-table-column prop="assessment_id" label="评估来源ID" min-width="250" /><el-table-column label="原患者与住院" min-width="230"><template #default="{ row }">#{{ row.patient_id }} · {{ row.admission_id }}</template></el-table-column><el-table-column prop="evaluation_at" label="明确评估时刻" min-width="220" /><el-table-column label="状态与版本"><template #default="{ row }">{{ statusLabel(row.status) }} · v{{ row.revision }}</template></el-table-column><el-table-column label="核对"><template #default="{ row }"><el-button @click="inspect(row)">核对冻结成人AKI评估</el-button></template></el-table-column></el-table></el-tab-pane></el-tabs>
      <p v-if="error" role="alert">{{ error }}</p><el-pagination v-if="total > 50" v-model:current-page="page" :page-size="50" :total="total" layout="prev,pager,next" @current-change="load" />
      <el-dialog v-model="createOpen" title="新建固定规则审核草稿" width="min(850px,96vw)" @closed="clearCreate"><el-form v-if="allowed" label-position="top" :disabled="creating" @submit.prevent><el-form-item label="固定规则"><el-select v-model="form.rule_id" aria-label="固定规则选项" placeholder="明确选择后台允许版本"><el-option v-for="option in options" :key="option.rule_id" :label="option.rule_id" :value="option.rule_id" /></el-select></el-form-item><p v-if="chosen">固定规则摘要 {{ chosen.recipe_digest }}；选择后也不能修改规则阈值或原输入策略。</p><el-form-item label="审核版本名称"><el-input v-model="form.name" aria-label="规则审核名称" maxlength="120" /></el-form-item><el-form-item label="原依据标识"><el-input v-model="form.evidence_reference" aria-label="规则依据标识" maxlength="1000" placeholder="至少5字；仅记录标识，不自动抓取链接" /></el-form-item><el-form-item label="规则审核依据"><el-input v-model="form.rationale" aria-label="规则审核依据" type="textarea" maxlength="2000" placeholder="至少20字，记录固定版本、实现和输入策略核对依据" /></el-form-item><p v-if="createError" role="alert">{{ createError }}</p></el-form><template #footer><el-button @click="createOpen = false">取消</el-button><el-button type="primary" :loading="creating" :disabled="!canCreate" @click="create">仅保存规则审核草稿</el-button></template></el-dialog>
      <el-dialog v-model="detailOpen" :title="detailKind === 'profiles' ? '固定风险规则审核' : detailKind === 'assessments' ? 'NEWS2冻结评估审计' : '成人AKI冻结评估审计'" width="min(1100px,96vw)" @closed="clearDetail"><div v-if="allowed" v-loading="inspecting"><p v-if="detailError" role="alert">{{ detailError }}</p><template v-if="detail"><p class="hash">{{ detailKind === 'profiles' ? detail.rule_profile_id : detail.assessment_id }} · {{ statusLabel(detail.status) }} · v{{ detail.revision }}<br />原内容摘要 {{ detail.content_hash }}<br />治理摘要 {{ detail.governance_hash }}</p>
        <template v-if="detailKind === 'profiles'"><p>{{ detail.name }} · {{ detail.rule_id }} · 规则摘要 {{ detail.recipe_digest }}</p><p>原依据：{{ detail.evidence_reference }}</p><p>原审核依据：{{ detail.rationale }}</p><p>固定输入策略（只读）：{{ JSON.stringify(detail.input_policy) }}</p><p>原发布 {{ detail.published_at || '未发布' }}；审核记录 {{ detail.review_note || '未提供' }}；审核依据 {{ detail.review_evidence_reference || '未提供' }}。</p><template v-if="detail.status === 'draft'"><el-checkbox v-model="termsConfirmed">我已核对固定规则版本、实现条款和输入策略</el-checkbox><el-input v-model="reviewEvidence" aria-label="规则发布依据标识" maxlength="2000" placeholder="至少5字，记录实际审核依据标识" /><el-input v-model="reviewNote" aria-label="规则发布审核说明" type="textarea" maxlength="2000" placeholder="至少20字；不代表已完成本院临床验证" /><el-button type="primary" :disabled="!termsConfirmed || reviewEvidence.trim().length < 5 || reviewNote.trim().length < 20" :loading="acting" @click="publish">审核并发布固定规则版本</el-button></template></template>
        <template v-else-if="detailKind === 'assessments'"><p>患者 #{{ detail.patient_id }} · 原住院 {{ detail.admission_id }} · 原窗 {{ detail.window_id }} · 原点 {{ detail.point_id }} · 规则 {{ detail.rule_profile_id }}</p><p>原观察 {{ detail.observed_at }}；评估登记 {{ detail.created_at }}。当前一致性 {{ detail.freshness?.state }}；当前可纳入 {{ detail.eligible === true ? '是，仍须核实适用性' : '否' }}。</p><p v-if="!detail.snapshot">响应未提供冻结原文，不能补写原测量或适用性事实。</p><template v-else><p>原年龄声明 {{ detail.snapshot.attestation.age_at_observation_years }}；原妊娠声明 {{ detail.snapshot.attestation.pregnancy_status }}；Scale {{ detail.snapshot.attestation.spo2_scale }}。</p><p>原年龄依据 {{ detail.snapshot.attestation.age_basis_note }}</p><p>原妊娠依据 {{ detail.snapshot.attestation.pregnancy_basis_note }}</p><p>原临床资格 {{ detail.snapshot.author_qualification?.role_at_creation }}；医生记录 {{ detail.snapshot.author_qualification?.doctor_id ?? '无' }}。Super身份不替代临床Scale 2资格。</p><p v-if="detail.snapshot.attestation.scale2_review">血气依据 {{ detail.snapshot.attestation.scale2_review.blood_gas_reference }}；临床决定依据 {{ detail.snapshot.attestation.scale2_review.clinical_decision_reference }}。</p><el-table :data="rawValues" aria-label="NEWS2审计冻结原测量"><el-table-column prop="key" label="原指标" /><el-table-column label="原值或缺失"><template #default="{ row }">{{ row.value ?? `未测（${row.absent_reason}）` }}</template></el-table-column><el-table-column prop="unit" label="原单位" /></el-table><p>原氧疗 {{ detail.snapshot.point.payload.supplemental_oxygen }}；原意识 {{ JSON.stringify(detail.snapshot.point.payload.consciousness) }}；原点时间 {{ detail.snapshot.point.observed_at }} / {{ detail.snapshot.point.recorded_at }}。</p></template></template>
        <template v-else><p>患者 #{{ detail.patient_id }} · 原住院 {{ detail.admission_id }} · 原窗 {{ detail.window_id }} · 规则 {{ detail.rule_profile_id }}</p><p>明确评估 {{ detail.evaluation_at }}；登记 {{ detail.created_at }}。当前一致性 {{ detail.freshness?.state }}；当前来源资格 {{ detail.eligible === true ? '可选择，仍须计算完整性核查' : '不允许当前计算，冻结原文仅审计' }}。</p><p v-if="!detail.snapshot">响应没有冻结原文，不补写原测量或临床声明。</p><template v-else><p>原年龄 {{ detail.snapshot.attestation.age_at_evaluation_years }}；原年龄依据 {{ detail.snapshot.attestation.age_basis_note }}。</p><p>原SCr用途确认 {{ detail.snapshot.attestation.serum_creatinine_confirmed }}；原临床依据 {{ detail.snapshot.attestation.creatinine_review_note ?? '未声明' }}。</p><p>原基线策略 {{ detail.snapshot.attestation.baseline_mode }}；近期升高原临床依据 {{ detail.snapshot.attestation.baseline_review_note ?? '未声明' }}。</p><p>原体重整段适用依据 {{ detail.snapshot.attestation.weight_basis_note ?? '未声明' }}；RRT原状态 {{ detail.snapshot.attestation.rrt_status }}；原启动 {{ detail.snapshot.attestation.rrt_started_at ?? '未声明' }}；原临床依据 {{ detail.snapshot.attestation.rrt_basis_note ?? '未声明' }}。</p><p>原签署身份 {{ detail.snapshot.author_qualification?.role_at_creation }} · 医生记录 {{ detail.snapshot.author_qualification?.doctor_id ?? '无' }}；管理身份不替代临床资格。</p><el-table :data="akiLabRows" aria-label="AKI审计冻结肌酐原值"><el-table-column prop="label" label="明确原用途" /><el-table-column label="原数据库值"><template #default="{ row }">{{ row.original.value_num ?? row.original.value_text ?? '未提供' }} {{ row.original.unit ?? '' }}</template></el-table-column><el-table-column prop="source.collected_at_utc" label="人工核实原采样UTC" min-width="220" /><el-table-column prop="source.admission_id" label="实际原住院" min-width="250" /></el-table><p v-if="detail.snapshot.weight_point">原体重 {{ detail.snapshot.weight_point.payload.measurements.body_weight.value ?? '未测' }} kg · {{ detail.snapshot.weight_point.observed_at }}。</p><el-table :data="detail.snapshot.urine_intervals" aria-label="AKI审计冻结原尿量"><el-table-column prop="start_at" label="原开始UTC" min-width="220" /><el-table-column prop="end_at" label="原结束UTC" min-width="220" /><el-table-column label="原尿量"><template #default="{ row }">{{ row.payload.volume_ml ?? `未测（${row.payload.absent_reason}）` }} mL</template></el-table-column><el-table-column prop="payload.collection_completeness" label="原收集完整性" /><el-table-column label="原患者总量声明"><template #default="{ row }">{{ row.payload.patient_total === true ? '是' : row.payload.patient_total === false ? '否' : '未知' }}</template></el-table-column></el-table><p>整段平均策略不是逐小时持续少尿证据；原0、未知和较早原住院分别保留，审计不自动计算、排除AKI或修订旧来源。</p></template></template>
        <template v-if="detail.status !== 'revoked' && (detailKind === 'profiles' || detail.can_revoke === true)"><el-input v-model="revokeReason" aria-label="固定风险治理撤销依据" type="textarea" maxlength="1000" placeholder="至少5字，说明撤销原因，不能恢复原版本" /><el-button type="danger" :disabled="revokeReason.trim().length < 5" :loading="acting" @click="revoke">撤销此{{ detailKind === 'profiles' ? '规则版本' : '评估来源' }}</el-button></template><p v-if="detail.status === 'revoked'">已撤销 {{ detail.revoked_at }}：{{ detail.revoke_reason }}；冻结原文仅供审计。</p>
      </template></div><template #footer><el-button @click="detailOpen = false">关闭</el-button></template></el-dialog>
    </template>
  </section>
</template>
<script setup>
import { computed, onActivated, onBeforeUnmount, onDeactivated, ref, watch } from "vue";
import { useStore } from "vuex";
import { createRiskRuleProfile, getAdminNews2Assessment, getAdminNews2Assessments, getRiskRuleOptions, getRiskRuleProfile, getRiskRuleProfiles, news2AssessmentMatches, publishRiskRuleProfile, revokeNews2Assessment, revokeRiskRuleProfile } from "@/api/aiNews2";
import { akiAssessmentMatches, getAdminAkiAssessment, getAdminAkiAssessments, revokeAkiAssessment } from "@/api/aiAki";
const auditKinds = { assessments: { list: getAdminNews2Assessments, detail: getAdminNews2Assessment, revoke: revokeNews2Assessment, matches: news2AssessmentMatches }, aki_assessments: { list: getAdminAkiAssessments, detail: getAdminAkiAssessment, revoke: revokeAkiAssessment, matches: akiAssessmentMatches } };
const store = useStore(), roles = computed(() => store.getters["user/permissions"] || []), allowed = computed(() => !!store.state.user.accessToken && roles.value.includes("super_admin"));
const profileRule = ref("");
const tab = ref("profiles"), filters = ref({ patient_id: "", admission_id: "", status: "" }), items = ref([]), options = ref([]), total = ref(null), page = ref(1), loading = ref(false), error = ref("");
const blank = () => ({ rule_id: "", name: "", evidence_reference: "", rationale: "" });
const form = ref(blank()), createOpen = ref(false), creating = ref(false), createError = ref(""), detail = ref(null), detailKind = ref("profiles"), detailOpen = ref(false), inspecting = ref(false), detailError = ref(""), termsConfirmed = ref(false), reviewNote = ref(""), reviewEvidence = ref(""), revokeReason = ref(""), acting = ref(false);
let epoch = 0, listSequence = 0, detailSequence = 0, createSequence = 0, inactive = false;
const session = () => JSON.stringify([store.state.user.accessToken, roles.value]), queryKey = () => JSON.stringify([tab.value, profileRule.value, filters.value, page.value]), capture = () => ({ epoch, session: session() }), current = ticket => ticket.epoch === epoch && ticket.session === session() && allowed.value && !inactive;
const chosen = computed(() => options.value.find(row => row.rule_id === form.value.rule_id));
const canCreate = computed(() => allowed.value && !creating.value && !!chosen.value && !!form.value.name.trim() && form.value.evidence_reference.trim().length >= 5 && form.value.rationale.trim().length >= 20);
const rawValues = computed(() => Object.entries(detail.value?.snapshot?.point?.payload?.measurements || {}).map(([key, row]) => ({ key, ...row })));
const akiLabRows = computed(() => [["index", "index_creatinine"], ["48小时比较", "comparison_48h"], ["明确基线", "baseline_creatinine"]].filter(([, key]) => detail.value?.snapshot?.[key]).map(([label, key]) => ({ label, source: detail.value.snapshot[key], original: detail.value.snapshot[key].snapshot?.original?.observation || {} })));
const statusLabel = value => ({ draft: "草稿", published: "已发布", active: "活动", revoked: "已撤销" }[value] || "未知状态");
function clearCreate() { createSequence++; createOpen.value = false; creating.value = false; createError.value = ""; form.value = blank(); }
function clearDetail() { detailSequence++; detail.value = null; detailError.value = ""; termsConfirmed.value = false; reviewNote.value = reviewEvidence.value = revokeReason.value = ""; inspecting.value = acting.value = false; }
function reset() { epoch++; listSequence++; clearCreate(); clearDetail(); detailOpen.value = false; items.value = []; options.value = []; filters.value = { patient_id: "", admission_id: "", status: "" }; total.value = null; page.value = 1; loading.value = false; error.value = ""; }
async function loadOptions() { if (!allowed.value || inactive) return; const ticket = capture(); try { const res = await getRiskRuleOptions(); if (!current(ticket)) return; if (!Array.isArray(res.data?.items) || res.data.items.some(row => !["news2_2017", "kdigo_aki_2012"].includes(row.rule_id) || !/^[a-f0-9]{64}$/.test(row.recipe_digest || ""))) throw new Error("固定规则目录未符合版本契约"); options.value = res.data.items; } catch (failure) { if (current(ticket)) error.value = failure?.message || "规则选项未能读取"; } }
async function load() { if (!allowed.value || inactive) return; const ticket = capture(), seq = ++listSequence, key = queryKey(); loading.value = true; items.value = []; error.value = ""; try { const patient = filters.value.patient_id.trim(); if (tab.value !== "profiles" && patient && (!/^[1-9]\d*$/.test(patient) || !Number.isSafeInteger(Number(patient)))) throw new Error("患者ID须为正整数"); const params = { page: page.value, page_size: 50, ...(tab.value === "profiles" && profileRule.value ? { rule_id: profileRule.value } : {}), ...(tab.value !== "profiles" ? { ...(patient ? { patient_id: Number(patient) } : {}), ...(filters.value.admission_id.trim() ? { admission_id: filters.value.admission_id.trim() } : {}), ...(filters.value.status ? { status: filters.value.status } : {}) } : {}) }; const res = await (tab.value === "profiles" ? getRiskRuleProfiles(params) : auditKinds[tab.value].list(params)); if (!current(ticket) || seq !== listSequence || key !== queryKey()) return; const values = res.data?.items; if (!Array.isArray(values) || (tab.value === "profiles" && values.some(row => (profileRule.value && row.rule_id !== profileRule.value) || !["news2_2017", "kdigo_aki_2012"].includes(row.rule_id))) || (tab.value !== "profiles" && values.some(row => (params.patient_id && row.patient_id !== params.patient_id) || (params.admission_id && row.admission_id !== params.admission_id)))) throw new Error("治理目录与查询范围不一致"); items.value = values; total.value = res.data.total; } catch (failure) { if (current(ticket) && seq === listSequence && key === queryKey()) error.value = failure?.message || "治理目录未能读取"; } finally { if (current(ticket) && seq === listSequence && key === queryKey()) loading.value = false; } }
function openCreate() { if (!allowed.value || inactive) return; clearCreate(); createOpen.value = true; }
async function create() { if (!canCreate.value || inactive) return; const ticket = capture(), seq = createSequence, payload = { ...form.value, expected_recipe_digest: chosen.value.recipe_digest }; creating.value = true; try { const res = await createRiskRuleProfile(payload); if (!current(ticket) || seq !== createSequence || !createOpen.value) return; const row = res.data; if (row?.status !== "draft" || row.revision !== 1 || row.name !== payload.name || row.rule_id !== payload.rule_id || row.recipe_digest !== payload.expected_recipe_digest || !/^[a-f0-9]{64}$/.test(row.content_hash || "")) throw new Error("草稿回执与所选固定规则版本不一致"); clearCreate(); await load(); } catch (failure) { if (current(ticket) && seq === createSequence) createError.value = failure?.message || "规则草稿保存失败"; } finally { if (current(ticket) && seq === createSequence) creating.value = false; } }
async function inspect(row) { if (!allowed.value || inactive) return; clearDetail(); const ticket = capture(), seq = detailSequence, kind = tab.value; detailKind.value = kind; detailOpen.value = true; inspecting.value = true; try { const res = await (kind === "profiles" ? getRiskRuleProfile(row.rule_profile_id) : auditKinds[kind].detail(row.assessment_id)); if (!current(ticket) || seq !== detailSequence || !detailOpen.value) return; if (kind === "profiles" ? res.data?.rule_profile_id !== row.rule_profile_id || res.data.rule_id !== row.rule_id || res.data.content_hash !== row.content_hash || res.data.recipe_digest !== row.recipe_digest : res.data?.assessment_id !== row.assessment_id || !auditKinds[kind].matches(res.data, row.patient_id, row.admission_id, row.window_id)) throw new Error("原详情与指定规则或评估范围不一致"); detail.value = res.data; } catch (failure) { if (current(ticket) && seq === detailSequence) detailError.value = failure?.message || "原详情未能核对"; } finally { if (current(ticket) && seq === detailSequence) inspecting.value = false; } }
async function publish() { if (!allowed.value || inactive || acting.value || detail.value?.status !== "draft" || !termsConfirmed.value || reviewNote.value.trim().length < 20 || reviewEvidence.value.trim().length < 5) return; await act("publish"); }
async function revoke() { if (!allowed.value || inactive || acting.value || !detail.value || detail.value.status === "revoked" || revokeReason.value.trim().length < 5 || (detailKind.value !== "profiles" && detail.value.can_revoke !== true)) return; await act("revoke"); }
async function act(action) { const ticket = capture(), seq = detailSequence, original = detail.value, kind = detailKind.value; const body = action === "publish" ? { expected_revision: original.revision, expected_recipe_digest: original.recipe_digest, implementation_terms_confirmed: true, review_note: reviewNote.value.trim(), review_evidence_reference: reviewEvidence.value.trim() } : { expected_revision: original.revision, reason: revokeReason.value.trim(), ...(kind !== "profiles" ? { patient_id: original.patient_id, admission_id: original.admission_id } : {}) }; acting.value = true; try { const res = await (action === "publish" ? publishRiskRuleProfile(original.rule_profile_id, body) : kind === "profiles" ? revokeRiskRuleProfile(original.rule_profile_id, body) : auditKinds[kind].revoke(original.assessment_id, body)); if (!current(ticket) || seq !== detailSequence || !detailOpen.value) return; const row = res.data; if ((kind === "profiles" ? row?.rule_profile_id !== original.rule_profile_id || row.rule_id !== original.rule_id || row.recipe_digest !== original.recipe_digest : row?.assessment_id !== original.assessment_id || !auditKinds[kind].matches(row, original.patient_id, original.admission_id, original.window_id)) || row.status !== (action === "publish" ? "published" : "revoked") || row.revision !== original.revision + 1 || row.content_hash !== original.content_hash) throw new Error("治理动作回执与原版本、状态或内容摘要不一致"); detail.value = row; termsConfirmed.value = false; reviewNote.value = reviewEvidence.value = revokeReason.value = ""; await load(); } catch (failure) { if (current(ticket) && seq === detailSequence) detailError.value = failure?.message || "治理动作失败，请重新核对权限和版本"; } finally { if (current(ticket) && seq === detailSequence) acting.value = false; } }
watch([tab, profileRule, () => JSON.stringify(filters.value)], () => { listSequence++; clearCreate(); page.value = 1; detailOpen.value = false; clearDetail(); items.value = []; load(); }, { flush: "sync" });
watch(session, () => { reset(); loadOptions(); load(); }, { immediate: true, flush: "sync" });
onDeactivated(() => { inactive = true; reset(); }); onActivated(() => { if (inactive) { inactive = false; reset(); loadOptions(); load(); } }); onBeforeUnmount(() => { inactive = true; reset(); });
</script>
